update public.learning_paths
set
  title = 'U.S. Health Care System',
  goal = 'U.S. Health Care System',
  summary = 'A first- or second-year core course introducing how the United States finances, organizes, regulates, delivers, measures, and reforms health care. Students learn to trace a person''s path through coverage and care, read health-system data, identify institutional incentives, analyze inequities, compare the United States with peer systems, and evaluate reform proposals using explicit goals and tradeoffs.',
  data = $ushcsjson${"slug": "u-s-health-care-system", "title": "U.S. Health Care System", "description": "A first- or second-year core course introducing how the United States finances, organizes, regulates, delivers, measures, and reforms health care. Students learn to trace a person's path through coverage and care, read health-system data, identify institutional incentives, analyze inequities, compare the United States with peer systems, and evaluate reform proposals using explicit goals and tradeoffs.", "topics": [{"id": "05087417-5dfa-4de7-b5a9-ba686c370c66", "type": "topic", "title": "Origins, Values, and Structure of the U.S. Health Care System", "description": "Explains how history, federalism, markets, professional institutions, and contested values produced a fragmented mix of public and private organizations.", "children": [{"id": "7fe9e0bc-276b-4256-bd2f-e21fcb342fb7", "type": "subtopic", "title": "Historical development", "description": "The system is easier to understand as layered policy choices than as a single design.", "children": [{"id": "d2397050-b29b-4368-9040-71d9985c9429", "type": "concept", "title": "Professionalization and hospital growth"}, {"id": "b154d46e-42ed-492e-be61-931ce3c776a5", "type": "concept", "title": "Employment-based insurance and tax policy"}, {"id": "228d3a42-d8bc-4db9-98e4-db3c786bb937", "type": "concept", "title": "Creation of Medicare and Medicaid"}, {"id": "963f40f7-941c-4b44-9b17-4fa4b2cfc005", "type": "concept", "title": "Managed care, ACA, and contemporary consolidation"}]}, {"id": "cc21f81a-a3c7-4ea5-80ef-af4a1460911a", "type": "subtopic", "title": "Organizational structure", "description": "Students identify the institutions that finance, organize, deliver, regulate, and receive care.", "children": [{"id": "630cdaab-07a0-4f83-95ae-922330ca3b31", "type": "concept", "title": "Patients, families, and communities"}, {"id": "63461520-1aeb-444b-b494-05983636f2e5", "type": "concept", "title": "Purchasers, payers, and intermediaries"}, {"id": "6ba63017-e202-4d6e-afb0-8fbb96ffb452", "type": "concept", "title": "Providers, suppliers, and systems"}, {"id": "7456afb3-2b2a-4f0e-b4c7-ffc6b9d1817f", "type": "concept", "title": "Regulators, accreditors, and public-health agencies"}]}, {"id": "7dbde7ec-8190-4483-a6b0-3431a5700c93", "type": "subtopic", "title": "Values and goals", "description": "System debates reflect competing views of health care as a right, good, service, investment, and public responsibility.", "children": [{"id": "6bc496ab-df73-44f3-b908-452004b814d4", "type": "concept", "title": "Access and universality"}, {"id": "b935bf6c-bca1-4c55-92d1-4a17e22768bb", "type": "concept", "title": "Quality and safety"}, {"id": "37b181a0-c110-437e-a827-3db4ca3e2140", "type": "concept", "title": "Efficiency and affordability"}, {"id": "4d0556b8-7281-4037-a288-60ac92534722", "type": "concept", "title": "Choice, equity, solidarity, and innovation"}]}]}, {"id": "5e04c5d1-2e97-4d96-bf1e-19616764c703", "type": "topic", "title": "Government Roles, Regulation, and Health Policy Institutions", "description": "Maps federal, state, local, tribal, and territorial authority and the agencies, legislatures, courts, and interest groups that shape health-system rules.", "children": [{"id": "12201ef0-cdbb-4790-b9ef-96928399080d", "type": "subtopic", "title": "Federalism", "description": "Authority is distributed across levels of government, creating variation and coordination problems.", "children": [{"id": "0e5385e3-0e53-4c5a-b49c-ef5da7cd4d10", "type": "concept", "title": "Federal powers and financing"}, {"id": "6a73efe5-82b1-491e-9004-e3f0f35c18ee", "type": "concept", "title": "State insurance, professional, and facility regulation"}, {"id": "30fdb3ee-0875-4f45-9542-c63004893f8f", "type": "concept", "title": "Local delivery and public health"}, {"id": "cf33c235-9374-4381-a747-b6ff50175773", "type": "concept", "title": "Tribal sovereignty and territorial systems"}]}, {"id": "9c9ebb6e-74be-4967-ab70-88f5a73cd3e2", "type": "subtopic", "title": "Institutions and agencies", "description": "Students learn which bodies make, administer, interpret, and evaluate policy.", "children": [{"id": "f45fb0e1-81bd-46ac-9ade-bfd2e8873a6d", "type": "concept", "title": "Congress, executive branch, and courts"}, {"id": "65d73a4f-ca24-4d47-9b9a-85e0db2f428c", "type": "concept", "title": "HHS, CMS, CDC, FDA, HRSA, AHRQ, and NIH"}, {"id": "0c8f28c6-82ec-44fa-8e51-15f661c08933", "type": "concept", "title": "State agencies and insurance departments"}, {"id": "fbaf9096-0f6c-4712-bd09-2e8b602c1d17", "type": "concept", "title": "Independent commissions and advisory bodies"}]}, {"id": "ef9e3378-9a39-489f-836f-41561bddc97b", "type": "subtopic", "title": "Policy process and influence", "description": "Formal authority interacts with organized interests, evidence, budgets, and public opinion.", "children": [{"id": "62ed3469-d75e-4e56-9a7b-9b9cb2e48c15", "type": "concept", "title": "Legislation and regulation"}, {"id": "7a149052-551b-48c0-acb8-8ebb23fbaff6", "type": "concept", "title": "Waivers and demonstrations"}, {"id": "38f15005-fb28-4f03-a955-976e39f5b198", "type": "concept", "title": "Litigation and judicial review"}, {"id": "637343fc-2af7-429a-94da-56abf9fe4189", "type": "concept", "title": "Interest groups, lobbying, advocacy, and media"}]}]}, {"id": "d9379ac3-d41f-482c-b83b-4f643b5ec38a", "type": "topic", "title": "Public and Private Financing", "description": "Shows where the health dollar comes from, how risk is pooled, who pays, and how taxes, premiums, cost sharing, and uncompensated care distribute burdens.", "children": [{"id": "e6c15520-49dd-4f1f-8411-0b15132b5311", "type": "subtopic", "title": "Sources of funds", "description": "Health care is financed through taxes, premiums, household payments, and cross-subsidies.", "children": [{"id": "17a91ce0-8921-4b71-ad21-81a80ae02779", "type": "concept", "title": "Federal, state, and local revenues"}, {"id": "d9e5f128-0c79-43c1-ae85-0dc8437a3239", "type": "concept", "title": "Employer and employee premiums"}, {"id": "67044ba1-da4c-49f3-83e4-ae4e6e50d3f8", "type": "concept", "title": "Individual premiums and cost sharing"}, {"id": "0b33ff3f-eaae-461d-972a-d6316506cf24", "type": "concept", "title": "Uncompensated care and charitable support"}]}, {"id": "aec39140-db81-4182-b96e-74c1e48b70f4", "type": "subtopic", "title": "Risk pooling", "description": "Pooling spreads uncertain costs, but enrollment and benefit rules distribute risk differently.", "children": [{"id": "df649da3-69f0-41bc-9d92-ea480e3e12dc", "type": "concept", "title": "Risk, adverse selection, and moral hazard"}, {"id": "80980110-5448-45b5-a620-26c037c532d1", "type": "concept", "title": "Community and experience rating"}, {"id": "4a19e2f2-f893-441f-b5a3-a510447bc001", "type": "concept", "title": "Reinsurance and risk adjustment"}, {"id": "4b8aafd4-c5b8-4254-88f2-255ccd61b87b", "type": "concept", "title": "Pooling size and fragmentation"}]}, {"id": "c930a90c-121f-4d81-8f03-aaae5d7bc75f", "type": "subtopic", "title": "Incidence and burden", "description": "Who writes the check is not always who ultimately bears the cost.", "children": [{"id": "9e5b0eac-6f2a-4b5e-a200-828128470541", "type": "concept", "title": "Wage tradeoffs"}, {"id": "9bf222cb-d981-445a-945d-bfff5392e234", "type": "concept", "title": "Tax incidence"}, {"id": "ff982971-1ae3-4f77-ab80-cfe3975304e1", "type": "concept", "title": "Premium and out-of-pocket burden"}, {"id": "8912e6d4-0b20-4e98-8e34-9e8dbc6d9785", "type": "concept", "title": "Regressive and progressive financing"}]}]}, {"id": "74227c2f-9007-403c-8af6-a1587d407eba", "type": "topic", "title": "Medicare, Medicaid, CHIP, and the Affordable Care Act", "description": "Compares eligibility, benefits, administration, financing, delivery arrangements, and current policy tensions across major public coverage programs.", "children": [{"id": "a186cde3-81b4-40ab-bb29-b89526ba6c3f", "type": "subtopic", "title": "Medicare", "description": "Medicare is a federal social insurance program with distinct parts, benefits, payment systems, and supplemental coverage.", "children": [{"id": "f42a994e-ae15-4102-8d35-b5a23b49132a", "type": "concept", "title": "Eligibility and Parts A–D"}, {"id": "d00e02a1-ab91-42d0-b541-32e6be3d21dc", "type": "concept", "title": "Traditional Medicare and Medicare Advantage"}, {"id": "607c1128-b516-4d82-a24d-938574cc6086", "type": "concept", "title": "Cost sharing and supplemental coverage"}, {"id": "cef524f3-5644-4af8-8254-dc05f4f9ac0e", "type": "concept", "title": "Payment, solvency, and access issues"}]}, {"id": "54e32c89-53ff-4383-abf8-124328b34672", "type": "subtopic", "title": "Medicaid and CHIP", "description": "These federal–state programs vary substantially in eligibility, benefits, delivery, and payment.", "children": [{"id": "89bcbbeb-c691-44ba-b48a-b06786d5bf34", "type": "concept", "title": "Eligibility categories and expansion"}, {"id": "98547ace-1b0f-4141-9e1a-b18de94b00b7", "type": "concept", "title": "Federal matching and state administration"}, {"id": "789b08de-7905-4e43-89a4-859efc168edf", "type": "concept", "title": "Managed care and fee-for-service"}, {"id": "c1b233ac-6802-4dcb-b2fe-b043c6df9cf7", "type": "concept", "title": "Children, disability, long-term services, and waivers"}]}, {"id": "2f27a3bb-0ee3-4fa9-8ce2-19c8d27ba706", "type": "subtopic", "title": "Affordable Care Act", "description": "The ACA reshaped individual coverage, insurance rules, Medicaid eligibility, and delivery reform.", "children": [{"id": "db985464-de01-401c-b42b-a59d2cdcaa2c", "type": "concept", "title": "Marketplaces and subsidies"}, {"id": "1c558bbd-8ef5-4768-9b8c-23b03459c2b6", "type": "concept", "title": "Consumer protections"}, {"id": "04946c08-1cad-4d06-be02-4fe1024f7e36", "type": "concept", "title": "Individual and employer provisions"}, {"id": "41976b7c-74aa-4eff-a69f-06438559835b", "type": "concept", "title": "Coverage gains, remaining gaps, and state variation"}]}]}, {"id": "91155c9f-bfc7-4e42-a25e-6b935c81e71b", "type": "topic", "title": "Private Insurance, Employer Coverage, and Managed Care", "description": "Examines benefit design, networks, utilization management, risk selection, employer sponsorship, marketplaces, and the patient experience of using insurance.", "children": [{"id": "a65082c3-ee16-499c-baf0-85b9a35ed105", "type": "subtopic", "title": "Employer-sponsored insurance", "description": "Employment remains a major coverage pathway shaped by tax policy, firm decisions, and labor markets.", "children": [{"id": "03e99923-a185-47f1-9778-5eb04508eca3", "type": "concept", "title": "Fully insured and self-funded plans"}, {"id": "36b3c548-e0a4-45c9-a5c9-50bc1c7472d0", "type": "concept", "title": "ERISA context"}, {"id": "abfe16f3-518f-4f69-9c8e-ca5962cda638", "type": "concept", "title": "Premium contributions and benefit design"}, {"id": "db6ed7fe-8a79-4970-b84c-edec1b1f5a87", "type": "concept", "title": "Job changes, COBRA, and portability"}]}, {"id": "54a3868e-a7ea-4dea-9216-dc1c223413ab", "type": "subtopic", "title": "Plan design", "description": "Insurance terms translate directly into affordability and access.", "children": [{"id": "36ce7b9a-a76c-4db1-9522-4a1e4e32bdc9", "type": "concept", "title": "Premium, deductible, copayment, and coinsurance"}, {"id": "9a466285-5e4f-4c36-addb-742044e36f68", "type": "concept", "title": "Out-of-pocket maximum"}, {"id": "7deb45c3-7be2-4682-88ac-114636c8c91a", "type": "concept", "title": "Covered benefits and exclusions"}, {"id": "0a368511-1f60-46cb-8927-1c80eb6e4aa1", "type": "concept", "title": "Formularies, tiers, and prior authorization"}]}, {"id": "06ccbebd-e410-4cea-a89a-f862c6380ec8", "type": "subtopic", "title": "Managed care", "description": "Managed care coordinates financing and delivery through networks and utilization tools.", "children": [{"id": "09535ee8-01c1-4259-9d92-ec047adecf4e", "type": "concept", "title": "HMO, PPO, EPO, and POS models"}, {"id": "954547da-e354-4a90-b365-8033db5e7dc4", "type": "concept", "title": "Networks and referrals"}, {"id": "ce03c693-0ef2-4fe1-ac32-2f46364dd6fe", "type": "concept", "title": "Utilization management"}, {"id": "10c320c2-d174-45ce-adf4-2dce21aa9159", "type": "concept", "title": "Risk adjustment, selection, and consumer protection"}]}]}, {"id": "77f5f834-0aef-4628-a9b4-b396fd9bcbc4", "type": "topic", "title": "Health Care Spending, Prices, Payment, and Incentives", "description": "Connects national spending and prices to fee-for-service, prospective payment, capitation, value-based payment, consolidation, and provider behavior.", "children": [{"id": "0160529a-b51a-4f08-a2bc-0ca1bb61143a", "type": "subtopic", "title": "Spending measurement", "description": "Students distinguish national totals, per-person spending, growth, price, volume, intensity, and administrative cost.", "children": [{"id": "61050393-5edf-466f-8cba-4a472f02483c", "type": "concept", "title": "National Health Expenditure Accounts"}, {"id": "244822f5-06c8-4d64-8a4c-a3fb63d3f779", "type": "concept", "title": "Payer and service categories"}, {"id": "ee6a3794-5aaa-401e-97f3-a03860b06877", "type": "concept", "title": "Nominal, real, and share-of-GDP measures"}, {"id": "63092caf-99fc-46ac-8b2f-c1667c4898cb", "type": "concept", "title": "Historical versus projected spending"}]}, {"id": "1ddc94cb-6c26-4132-ad4c-fb321ecb9537", "type": "subtopic", "title": "Provider payment", "description": "Payment units and risk allocation shape service volume, coordination, coding, and investment.", "children": [{"id": "6dc3a79a-613c-4c2e-bea5-6e4c93cfb660", "type": "concept", "title": "Fee-for-service"}, {"id": "a2ac5662-f266-4681-8ca2-41b8a73c56f9", "type": "concept", "title": "Prospective and diagnosis-related payment"}, {"id": "1cee8090-3660-480a-a95f-e745cd0ad1ba", "type": "concept", "title": "Bundled payment and shared savings"}, {"id": "75605e2b-bf0c-478d-ac59-ca6b86df91e8", "type": "concept", "title": "Capitation and global budgets"}]}, {"id": "649782e5-3137-4dd4-8cf2-f537ea51dbf9", "type": "subtopic", "title": "Prices and market power", "description": "High prices can reflect bargaining leverage, consolidation, regulation, input cost, and benefit design.", "children": [{"id": "aa5101d5-faa1-45d5-a59b-8b85e02cf879", "type": "concept", "title": "Commercial and administered prices"}, {"id": "de95654f-27a6-49c2-86d5-9b6b827a3559", "type": "concept", "title": "Hospital and physician consolidation"}, {"id": "326028b1-c83d-4ad0-b529-c4ed351cecf8", "type": "concept", "title": "Negotiated rates and transparency"}, {"id": "c2dedb42-e710-4f7c-81a0-423babbadde9", "type": "concept", "title": "Competition policy and rate regulation"}]}]}, {"id": "f7539338-2a28-4f36-9013-863262618415", "type": "topic", "title": "Hospitals, Physicians, and Ambulatory Care", "description": "Describes how care is organized across hospitals, medical groups, community health centers, retail and virtual settings, and increasingly consolidated systems.", "children": [{"id": "03b3b3d2-aa5d-43ab-ad99-568f726ef2d4", "type": "subtopic", "title": "Hospitals and health systems", "description": "Hospitals combine clinical, emergency, teaching, business, and community functions.", "children": [{"id": "85926be4-5980-4b8f-bfdf-d1fee7291c4c", "type": "concept", "title": "Ownership and tax status"}, {"id": "a61c660e-2e8a-44b4-84a9-18e91f888778", "type": "concept", "title": "Service lines and levels of care"}, {"id": "398bfd57-4bd3-401e-bd3b-dd05c3ab7512", "type": "concept", "title": "Academic, safety-net, rural, and specialty hospitals"}, {"id": "a94c93a9-7162-4316-a654-af7fac1efb67", "type": "concept", "title": "Integration, consolidation, and community benefit"}]}, {"id": "330c3f9c-c355-4058-9da9-dccb55a2a486", "type": "subtopic", "title": "Physician organization", "description": "Practice structure affects autonomy, access, coordination, and payment.", "children": [{"id": "a9828020-214a-4ed1-a556-8aa7e956bf73", "type": "concept", "title": "Independent and employed practice"}, {"id": "c88fc205-5c2b-407c-8bab-390b515cdc3d", "type": "concept", "title": "Medical groups and integrated systems"}, {"id": "2d938ec0-bb52-4e6a-98d1-a489e061bea3", "type": "concept", "title": "Primary and specialty care"}, {"id": "cd62ddde-3759-4a91-a6a9-abcb68b860fd", "type": "concept", "title": "Referral relationships and accountable care"}]}, {"id": "cfb3ca2e-0861-4f30-9685-33d9f6d9d0fe", "type": "subtopic", "title": "Ambulatory transformation", "description": "Care increasingly occurs outside the hospital through new settings and delivery models.", "children": [{"id": "3952a0d7-3599-43b1-878e-82ef5b1dbce9", "type": "concept", "title": "Community health centers"}, {"id": "1c2fcfc9-7a4d-42a1-9629-e2dc6bf6dabb", "type": "concept", "title": "Urgent, retail, and home-based care"}, {"id": "dabae026-eaed-4cdf-9aff-eae8c5d19711", "type": "concept", "title": "Telehealth and digital care"}, {"id": "03cf7b23-4c20-42da-ba3c-c55918713abc", "type": "concept", "title": "Hospital-at-home and site-neutral policy"}]}]}, {"id": "db60fc24-6103-4f04-ad07-76169e426ce2", "type": "topic", "title": "Health Workforce and Professional Practice", "description": "Analyzes workforce supply, distribution, training, scope, teams, labor conditions, burnout, and the structural causes of shortages and maldistribution.", "children": [{"id": "8fa79ce0-ce83-43c3-9019-6f3d21dd788e", "type": "subtopic", "title": "Supply and distribution", "description": "National headcounts can conceal shortages by geography, specialty, population, and setting.", "children": [{"id": "b7eea2ca-0431-41ba-9655-689c59c164a6", "type": "concept", "title": "Training pipeline and graduate education"}, {"id": "dfaba387-8de6-4296-9b2c-ea4cc2bd9968", "type": "concept", "title": "Licensure and scope of practice"}, {"id": "a932d346-d2d2-4970-9bf7-483f3671667b", "type": "concept", "title": "Health professional shortage areas"}, {"id": "3e2d3721-36a1-4662-9e27-8910089fba13", "type": "concept", "title": "Rural and underserved distribution"}]}, {"id": "f13219e9-ede7-4018-8f6f-ea04925acbe4", "type": "subtopic", "title": "Teams and roles", "description": "Modern care depends on coordination across professions and community workers.", "children": [{"id": "ed1159e2-cb7a-4fa6-aa2d-bae878024267", "type": "concept", "title": "Physicians, nurses, advanced practice clinicians"}, {"id": "1138dc2d-8440-466c-90c7-12a5268ac752", "type": "concept", "title": "Allied health, pharmacy, behavioral health, and oral health"}, {"id": "61c56498-13b2-4a76-bdba-f2affed14a67", "type": "concept", "title": "Community health workers and peer support"}, {"id": "de6c8d3e-3367-4559-bad1-b070baf08920", "type": "concept", "title": "Team-based and interprofessional care"}]}, {"id": "834da021-e0f5-42dd-b930-30ebaccb6e95", "type": "subtopic", "title": "Work conditions", "description": "Labor markets and organizational environments affect capacity, safety, retention, and equity.", "children": [{"id": "56eb1a0f-15f7-4287-aaf1-358e970da471", "type": "concept", "title": "Compensation and productivity"}, {"id": "38b945a8-41d7-49ef-8c02-c6b64e9504d4", "type": "concept", "title": "Burnout, moral distress, and turnover"}, {"id": "4a6ac41f-f63e-4fe7-89f1-21593ca7b1e3", "type": "concept", "title": "Unionization and staffing policy"}, {"id": "bc641722-ad1f-4001-9a66-da356148d5b0", "type": "concept", "title": "Diversity, inclusion, and career pathways"}]}]}, {"id": "1d25f155-8af6-41ac-a5c7-93b11a60d190", "type": "topic", "title": "Pharmaceuticals, Devices, and Health Technology", "description": "Follows innovation from research and regulation through pricing, coverage, prescribing, safety surveillance, access, and evidence of comparative value.", "children": [{"id": "6fe3cca8-6f58-4e57-b905-1827b699709e", "type": "subtopic", "title": "Innovation pathway", "description": "Products move from discovery through trials, regulation, manufacturing, adoption, and surveillance.", "children": [{"id": "1a26e3a5-